use gpui_dataset_transformation::{ThresholdMode,append_datasets,clip_sphere,decimate,threshold};
use gpui_mesh::{Association,Cells,DataSet,Field};
use gpui_profiler::AllocProbe;
use std::hint::black_box;
use std::time::Instant;

fn grid(n:usize,all_shapes:bool)->DataSet {
    let mut data=DataSet::structured_grid("source",[n;3],[0.0;3],[1.0;3]).unwrap();
    let points=data.point_count();let cells=data.cell_count();
    data.point_data.push(Field::scalar("p",data.positions.iter().map(|p|p[0]+2.0*p[1]+3.0*p[2]).collect::<Vec<_>>()));
    data.point_data.push(Field::vector("v",data.positions.iter().copied().collect::<Vec<_>>()));
    data.cell_data.push(Field::scalar("c",vec![0.25;cells]).on_cells());
    data.cell_data.push(Field::vector("cv",vec![[0.5,0.25,0.125];cells]).on_cells());
    if all_shapes {
        data.point_data.push(Field::tensor("t",vec![[1.0,2.0,3.0,0.0,0.0,0.0];points]));
        data.point_data.push(Field::complex("z",vec![[3.0,4.0];points]));
        data.cell_data.push(Field::tensor("ct",vec![[1.0;6];cells]).on_cells());
        data.cell_data.push(Field::complex("cz",vec![[3.0,4.0];cells]).on_cells());
    }
    data
}

fn check(output:&DataSet,n:usize,case:&str) {
    output.validate().unwrap();
    let (points,cells)=if case=="decimate_merge" {((n/2).pow(3),(n/2-1).pow(3))}
        else if case.starts_with("append_both") {(2*n.pow(3),2*(n-1).pow(3))}
        else if case=="threshold_empty" {(0,0)} else {(n.pow(3),(n-1).pow(3))};
    assert_eq!(output.point_count(),points);assert_eq!(output.cell_count(),cells);
    let scalar=output.field(Association::Point,"p").unwrap().as_scalar().unwrap();
    let vector=output.field(Association::Point,"v").unwrap().as_vector().unwrap();
    for (index,p) in output.positions.iter().enumerate() {
        assert!((scalar[index]-(p[0]+2.0*p[1]+3.0*p[2])).abs()<1e-12);
        assert_eq!(vector[index],*p);
    }
    assert!(output.cell_data[0].as_scalar().unwrap().iter().all(|&v|v==0.25));
}

fn measure(n:usize,case:&str,mut run:impl FnMut()->DataSet) {
    let warm=black_box(run());check(&warm,n,case);drop(warm);
    let mut times=Vec::with_capacity(5);let mut calls=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
    for _ in 0..5 {
        let mut allocations=AllocProbe::new();let start=Instant::now();let output=black_box(run());let elapsed=start.elapsed().as_nanos();let sample=allocations.sample("geometry");
        times.push(elapsed);calls.push(sample.count);bytes.push(sample.bytes);check(&output,n,case);drop(output);
    }
    println!(r#"{{"n":{n},"case":"{case}","times_ns":{times:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}

fn main() {
    let empty=DataSet::new("empty",vec![],Cells::from_cells(&[]));
    for n in [8usize,16,24] {
        let data=grid(n,false);
        measure(n,"decimate_merge",||decimate(&data,2.0).unwrap());
        measure(n,"decimate_identity",||decimate(&data,0.25).unwrap());
        measure(n,"append_both",||append_datasets(&data,&data).unwrap());
        measure(n,"append_empty",||append_datasets(&data,&empty).unwrap());
        measure(n,"threshold_all",||threshold(&data,"c",Association::Cell,0.0,1.0,ThresholdMode::All).unwrap());
        measure(n,"threshold_empty",||threshold(&data,"c",Association::Cell,2.0,3.0,ThresholdMode::All).unwrap());
        measure(n,"sphere_all",||clip_sphere(&data,[0.0;3],1e6,true,ThresholdMode::All).unwrap());
        let data=grid(n,true);
        measure(n,"append_both_all_shapes",||append_datasets(&data,&data).unwrap());
        measure(n,"threshold_all_shapes",||threshold(&data,"c",Association::Cell,0.0,1.0,ThresholdMode::All).unwrap());
        measure(n,"sphere_all_shapes",||clip_sphere(&data,[0.0;3],1e6,true,ThresholdMode::All).unwrap());
    }
}
